#!/usr/bin/env python3
# Some portions generated by Codex. Preserve ordering and paths; verify exact structural reconstruction.
import pathlib,json,sys,hashlib
p=pathlib.Path(sys.argv[1]);raw=p.read_bytes();original=json.loads(raw); entries={};arms={}
for arm,items in original.items():
 ids=[]
 for item in items:
  identity=hashlib.sha256(json.dumps(item,separators=(',',':')).encode()).hexdigest()
  if identity not in entries:
   prefix=item['entry'];files=[]
   for name,sha in item['sha256'].items():
    assert name.startswith(prefix),(prefix,name)
    files.append([name[len(prefix):],sha])
   entries[identity]={'entry':prefix,'suffixAndSha256':files}
  ids.append(identity)
 arms[arm]=ids
out={'format':'ordered-entry-prefix-dedup-v1','originalSha256':hashlib.sha256(raw).hexdigest(),'arms':arms,'entries':entries}
reconstructed={arm:[{'entry':entries[i]['entry'],'sha256':{entries[i]['entry']+suffix:sha for suffix,sha in entries[i]['suffixAndSha256']}} for i in ids] for arm,ids in arms.items()}
assert reconstructed==original
# Original writer used indent2, no trailing newline; require byte-for-byte reconstruction too.
assert json.dumps(reconstructed,indent=2).encode()==raw
q=p.with_name('runtime-manifest-deduplicated.json');q.write_text(json.dumps(out,indent=2));print(f'{p.stat().st_size} bytes -> {q.stat().st_size} bytes; exact reconstruction verified')
